  1→const DEFAULT_INDEX_KEY = 'chess_game_index';
  2→const DEFAULT_GAME_PREFIX = 'chess_game_';
  3→
  4→let currentUser = null;
  5→
  6→export function setCurrentUser(accountAddress) {
  7→  currentUser = accountAddress || null;
  8→}
  9→
 10→function getIndexKey() {
 11→  return currentUser ? `chess_${currentUser}_index` : DEFAULT_INDEX_KEY;
 12→}
 13→
 14→function getGamePrefix() {
 15→  return currentUser ? `chess_${currentUser}_game_` : DEFAULT_GAME_PREFIX;
 16→}
 17→
 18→function generateId() {
 19→  return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
 20→}
 21→
 22→export function createGame(engineColor) {
 23→  const id = generateId();
 24→  const now = new Date().toISOString();
 25→  const gameState = {
 26→    id,
 27→    board: null, // null = use INITIAL_BOARD default
 28→    currentTurn: 'white',
 29→    moveHistory: [],
 30→    enPassantTarget: null,
 31→    movedPieces: [],
 32→    halfMoveClock: 0,
 33→    positionHistory: [],
 34→    engineColor,
 35→    result: '*',
 36→    createdAt: now,
 37→    updatedAt: now,
 38→  };
 39→
 40→  try {
 41→    localStorage.setItem(getGamePrefix() + id, JSON.stringify(gameState));
 42→    const index = getIndex();
 43→    index.unshift({ id, createdAt: now, updatedAt: now, result: '*', moveCount: 0, engineColor });
 44→    localStorage.setItem(getIndexKey(), JSON.stringify(index));
 45→  } catch (e) {
 46→    console.error('Failed to save game:', e);
 47→    alert('Could not save game. localStorage may be full.');
 48→  }
 49→
 50→  return gameState;
 51→}
 52→
 53→export function saveGame(gameState) {
 54→  const now = new Date().toISOString();
 55→  const updated = { ...gameState, updatedAt: now, movedPieces: [...gameState.movedPieces] };
 56→
 57→  try {
 58→    localStorage.setItem(getGamePrefix() + gameState.id, JSON.stringify(updated));
 59→    const index = getIndex();
 60→    const entry = index.find(g => g.id === gameState.id);
 61→    if (entry) {
 62→      entry.updatedAt = now;
 63→      entry.result = gameState.result;
 64→      entry.moveCount = gameState.moveHistory.length;
 65→      localStorage.setItem(getIndexKey(), JSON.stringify(index));
 66→    }
 67→  } catch (e) {
 68→    console.error('Failed to save game:', e);
 69→    alert('Could not save game. localStorage may be full.');
 70→  }
 71→}
 72→
 73→export function loadGame(gameId) {
 74→  const raw = localStorage.getItem(getGamePrefix() + gameId);
 75→  if (!raw) return null;
 76→  const state = JSON.parse(raw);
 77→  state.movedPieces = new Set(state.movedPieces);
 78→  return state;
 79→}
 80→
 81→export function listGames() {
 82→  return getIndex();
 83→}
 84→
 85→export function deleteGame(gameId) {
 86→  localStorage.removeItem(getGamePrefix() + gameId);
 87→  const index = getIndex().filter(g => g.id !== gameId);
 88→  localStorage.setItem(getIndexKey(), JSON.stringify(index));
 89→}
 90→
 91→export function clearAllGames() {
 92→  const index = getIndex();
 93→  index.forEach(g => localStorage.removeItem(getGamePrefix() + g.id));
 94→  localStorage.removeItem(getIndexKey());
 95→}
 96→
 97→export function markGamePublished(gameId, txHash) {
 98→  const raw = localStorage.getItem(getGamePrefix() + gameId);
 99→  if (!raw) return;
100→  const state = JSON.parse(raw);
101→  state.txHash = txHash;
102→  localStorage.setItem(getGamePrefix() + gameId, JSON.stringify(state));
103→
104→  const index = getIndex();
105→  const entry = index.find(g => g.id === gameId);
106→  if (entry) {
107→    entry.txHash = txHash;
108→    localStorage.setItem(getIndexKey(), JSON.stringify(index));
109→  }
110→}
111→
112→function getIndex() {
113→  const raw = localStorage.getItem(getIndexKey());
114→  return raw ? JSON.parse(raw) : [];
115→}
