  1→import { useState, useEffect } from 'react';
  2→
  3→import './App.css';
  4→import Chessboard from './Chessboard';
  5→import GameList from './components/GameList';
  6→import AuthGate from './components/AuthGate';
  7→import GameSetup from './components/GameSetup';
  8→import JoinGame from './components/JoinGame';
  9→import WaitingRoom from './components/WaitingRoom';
 10→import OnlineChessboard from './components/OnlineChessboard';
 11→import { createGame, saveGame, loadGame, markGamePublished, setCurrentUser } from './utils/gameManager';
 12→import { usePasskeyAuth } from './hooks/usePasskeyAuth';
 13→import { usePasskeyPublish } from './hooks/usePasskeyPublish';
 14→import { useServerAuth } from './hooks/useServerAuth';
 15→import { GAME_SERVER_URL } from './config';
 16→
 17→// Persist/restore online game session across reloads
 18→const SS_ONLINE_KEY = 'online_game_session';
 19→
 20→function saveOnlineSession(view, roomId, inviteCode) {
 21→  if (view === 'online' || view === 'waiting') {
 22→    localStorage.setItem(SS_ONLINE_KEY, JSON.stringify({ view, roomId, inviteCode }));
 23→  } else {
 24→    localStorage.removeItem(SS_ONLINE_KEY);
 25→  }
 26→}
 27→
 28→function loadOnlineSession() {
 29→  try {
 30→    const raw = localStorage.getItem(SS_ONLINE_KEY);
 31→    return raw ? JSON.parse(raw) : null;
 32→  } catch { return null; }
 33→}
 34→
 35→function App() {
 36→  const saved = loadOnlineSession();
 37→  const [view, setView] = useState(saved?.view || 'list');
 38→  const [activeGame, setActiveGame] = useState(null);
 39→  const [publishStatus, setPublishStatus] = useState(null);
 40→
 41→  // Online game state
 42→  const [onlineRoomId, setOnlineRoomId] = useState(saved?.roomId || null);
 43→  const [onlineInviteCode, setOnlineInviteCode] = useState(saved?.inviteCode || null);
 44→
 45→  const passkey = usePasskeyAuth();
 46→  const serverAuth = useServerAuth({
 47→    isAuthenticated: passkey.isAuthenticated,
 48→    account: passkey.account,
 49→    username: passkey.username,
 50→  });
 51→  const { publishGame: passkeyPublish } = usePasskeyPublish({
 52→    account: passkey.account,
 53→    credentialId: passkey.credentialId,
 54→    rawId: passkey.rawId,
 55→  });
 56→
 57→  // Persist online session to sessionStorage on state changes
 58→  useEffect(() => {
 59→    saveOnlineSession(view, onlineRoomId, onlineInviteCode);
 60→  }, [view, onlineRoomId, onlineInviteCode]);
 61→
 62→  // Scope game storage to the authenticated user
 63→  useEffect(() => {
 64→    if (passkey.isAuthenticated && passkey.account) {
 65→      setCurrentUser(passkey.account);
 66→    } else {
 67→      setCurrentUser(null);
 68→    }
 69→  }, [passkey.isAuthenticated, passkey.account]);
 70→
 71→  const handleLogout = () => {
 72→    passkey.logout();
 73→    serverAuth.logout();
 74→    setActiveGame(null);
 75→    setPublishStatus(null);
 76→    setOnlineRoomId(null);
 77→    setOnlineInviteCode(null);
 78→    setView('list');
 79→  };
 80→
 81→  const handleNewGame = () => {
 82→    setView('setup');
 83→  };
 84→
 85→  // Local AI game start
 86→  const handleStartLocal = (color) => {
 87→    const engineColor = color === 'white' ? 'black' : 'white';
 88→    const game = createGame(engineColor);
 89→    setActiveGame(game);
 90→    setView('playing');
 91→  };
 92→
 93→  // Online game start
 94→  const handleStartOnline = async (color) => {
 95→    if (!serverAuth.serverToken) return;
 96→
 97→    try {
 98→      const resp = await fetch(`${GAME_SERVER_URL}/api/rooms`, {
 99→        method: 'POST',
100→        headers: {
101→          'Content-Type': 'application/json',
102→          'Authorization': `Bearer ${serverAuth.serverToken}`,
103→        },
104→        body: JSON.stringify({ color, opponent: 'human' }),
105→      });
106→
107→      const data = await resp.json();
108→      if (!resp.ok) {
109→        console.error('Create room failed:', data.error);
110→        return;
111→      }
112→
113→      setOnlineRoomId(data.roomId);
114→      setOnlineInviteCode(data.inviteCode);
115→      setView('waiting');
116→    } catch (err) {
117→      console.error('Create room error:', err);
118→    }
119→  };
120→
121→  const handleJoinGame = () => {
122→    setView('join');
123→  };
124→
125→  const handleJoined = (roomId) => {
126→    setOnlineRoomId(roomId);
127→    setView('online');
128→  };
129→
130→  const handleWaitingGameStart = (roomId) => {
131→    setOnlineRoomId(roomId);
132→    setView('online');
133→  };
134→
135→  const handleResumeGame = (gameId) => {
136→    const game = loadGame(gameId);
137→    if (game) {
138→      setActiveGame(game);
139→      setView('playing');
140→    }
141→  };
142→
143→  const handleSave = (state) => {
144→    if (!activeGame) return;
145→    saveGame({ ...state, id: activeGame.id, engineColor: activeGame.engineColor, createdAt: activeGame.createdAt });
146→  };
147→
148→  const handleGameEnd = async (result) => {
149→    if (!activeGame) return;
150→
151→    const latestState = loadGame(activeGame.id);
152→    if (latestState) {
153→      latestState.result = result;
154→      saveGame(latestState);
155→    }
156→    setActiveGame(prev => ({ ...prev, result }));
157→
158→    const finishedGame = latestState || { ...activeGame, result };
159→
160→    setPublishStatus('pending');
161→    const publishResult = await passkeyPublish(finishedGame);
162→
163→    if (publishResult.published) {
164→      setPublishStatus('success');
165→      markGamePublished(finishedGame.id, publishResult.txHash);
166→      setTimeout(() => setPublishStatus(null), 4000);
167→    } else if (['no-contract-address', 'passkey-not-authenticated'].includes(publishResult.reason)) {
168→      setPublishStatus(null);
169→    } else {
170→      setPublishStatus('error');
171→      setTimeout(() => setPublishStatus(null), 5000);
172→    }
173→  };
174→
175→  const handleBackToList = () => {
176→    setActiveGame(null);
177→    setPublishStatus(null);
178→    setOnlineRoomId(null);
179→    setOnlineInviteCode(null);
180→    setView('list');
181→  };
182→
183→  // Unauthenticated: show auth gate only
184→  if (!passkey.isAuthenticated) {
185→    return <AuthGate onSignup={passkey.signup} onLogin={passkey.login} />;
186→  }
187→
188→  return (
189→    <div className="app">
190→      <header className="app-header">
191→        <h1>Chess Board</h1>
192→        <div className="passkey-status">
193→          <span className="passkey-badge" title={passkey.account}>
194→            {passkey.username || passkey.account?.slice(0, 6) + '...' + passkey.account?.slice(-4)}
195→          </span>
196→          {serverAuth.isConnected && <span className="server-badge">Online</span>}
197→          <button className="passkey-logout" onClick={handleLogout}>Logout</button>
198→        </div>
199→      </header>
200→
201→      {publishStatus && (
202→        <div className={`publish-toast ${publishStatus}`}>
203→          {publishStatus === 'pending' && 'Publishing game on-chain...'}
204→          {publishStatus === 'success' && 'Game published on-chain!'}
205→          {publishStatus === 'error' && 'Failed to publish on-chain'}
206→        </div>
207→      )}
208→
209→      {view === 'list' && (
210→        <GameList
211→          onNewGame={handleNewGame}
212→          onResumeGame={handleResumeGame}
213→          onResumeOnline={(roomId) => { setOnlineRoomId(roomId); setView('online'); }}
214→          serverToken={serverAuth.serverToken}
215→        />
216→      )}
217→
218→      {view === 'setup' && (
219→        <GameSetup
220→          onStartLocal={handleStartLocal}
221→          onStartOnline={handleStartOnline}
222→          onJoinGame={handleJoinGame}
223→          onCancel={() => setView('list')}
224→          isServerConnected={serverAuth.isConnected}
225→        />
226→      )}
227→
228→      {view === 'join' && (
229→        <JoinGame
230→          serverToken={serverAuth.serverToken}
231→          onJoined={handleJoined}
232→          onCancel={() => setView('setup')}
233→        />
234→      )}
235→
236→      {view === 'waiting' && (
237→        <WaitingRoom
238→          inviteCode={onlineInviteCode}
239→          serverToken={serverAuth.serverToken}
240→          roomId={onlineRoomId}
241→          onGameStart={handleWaitingGameStart}
242→          onCancel={handleBackToList}
243→        />
244→      )}
245→
246→      {view === 'online' && onlineRoomId && (
247→        <OnlineChessboard
248→          key={onlineRoomId}
249→          serverToken={serverAuth.serverToken}
250→          roomId={onlineRoomId}
251→          onBackToList={handleBackToList}
252→        />
253→      )}
254→
255→      {view === 'playing' && activeGame && (
256→        <Chessboard
257→          key={activeGame.id}
258→          initialState={activeGame}
259→          onSave={handleSave}
260→          onGameEnd={handleGameEnd}
261→          onBackToList={handleBackToList}
262→          engineColorProp={activeGame.engineColor}
263→        />
264→      )}
265→    </div>
266→  );
267→}
268→
269→export default App;
