 1→import { useState, useEffect, useCallback } from 'react';
 2→import { GAME_SERVER_URL } from '../config';
 3→const LS_TOKEN_KEY = 'server_auth_token';
 4→
 5→export function useServerAuth({ isAuthenticated, account, username }) {
 6→  const [serverToken, setServerToken] = useState(() => localStorage.getItem(LS_TOKEN_KEY));
 7→  const [isConnected, setIsConnected] = useState(() => !!localStorage.getItem(LS_TOKEN_KEY));
 8→
 9→  // Bridge passkey auth to server token — also validates/re-bridges stale tokens
10→  useEffect(() => {
11→    if (!isAuthenticated || !account || !username) {
12→      setServerToken(null);
13→      setIsConnected(false);
14→      localStorage.removeItem(LS_TOKEN_KEY);
15→      return;
16→    }
17→
18→    let cancelled = false;
19→
20→    async function ensureValidToken() {
21→      const existing = localStorage.getItem(LS_TOKEN_KEY);
22→
23→      // If we have a stored token, validate it
24→      if (existing) {
25→        try {
26→          const resp = await fetch(`${GAME_SERVER_URL}/api/rooms`, {
27→            headers: { 'Authorization': `Bearer ${existing}` },
28→          });
29→          if (resp.ok) {
30→            // Token is valid
31→            if (!cancelled) {
32→              setServerToken(existing);
33→              setIsConnected(true);
34→            }
35→            return;
36→          }
37→        } catch {}
38→        // Token is stale/invalid — clear it and re-bridge
39→        localStorage.removeItem(LS_TOKEN_KEY);
40→      }
41→
42→      // Bridge: get a new token from the server
43→      try {
44→        const resp = await fetch(`${GAME_SERVER_URL}/api/auth/token`, {
45→          method: 'POST',
46→          headers: { 'Content-Type': 'application/json' },
47→          body: JSON.stringify({ passkeyAddress: account, username }),
48→        });
49→
50→        if (!resp.ok) {
51→          console.error('Server auth bridge failed:', await resp.text());
52→          if (!cancelled) setIsConnected(false);
53→          return;
54→        }
55→
56→        const data = await resp.json();
57→        if (!cancelled) {
58→          localStorage.setItem(LS_TOKEN_KEY, data.token);
59→          setServerToken(data.token);
60→          setIsConnected(true);
61→        }
62→      } catch (err) {
63→        console.error('Server auth bridge error:', err);
64→        if (!cancelled) setIsConnected(false);
65→      }
66→    }
67→
68→    ensureValidToken();
69→    return () => { cancelled = true; };
70→  }, [isAuthenticated, account, username]);
71→
72→  const logout = useCallback(() => {
73→    localStorage.removeItem(LS_TOKEN_KEY);
74→    setServerToken(null);
75→    setIsConnected(false);
76→  }, []);
77→
78→  return { serverToken, isConnected, logout };
79→}
