 11→function generateInviteCode(db) {
 12→  const checkCode = db.prepare('SELECT id FROM rooms WHERE invite_code = ?');
 13→  for (let attempt = 0; attempt < 20; attempt++) {
 14→    const word = CHESS_WORDS[Math.floor(Math.random() * CHESS_WORDS.length)];
 15→    const num = String(Math.floor(Math.random() * 100)).padStart(2, '0');
 16→    const code = word + num;
 17→    if (!checkCode.get(code)) {
 18→      return code;
 19→    }
 20→  }
 21→  // Fallback to UUID prefix if all collide (extremely unlikely)
 22→  return uuidv4().slice(0, 8).toUpperCase();
 23→}
