  9→function bufToHex(buf) {
 10→  return '0x' + Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('');
 11→}
 12→
 13→function base64urlEncode(buf) {
 14→  return btoa(String.fromCharCode(...new Uint8Array(buf)))
 15→    .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
 16→}
 17→
 18→function base64urlDecode(str) {
 19→  str = str.replace(/-/g, '+').replace(/_/g, '/');
 20→  while (str.length % 4) str += '=';
 21→  const binary = atob(str);
 22→  const bytes = new Uint8Array(binary.length);
 23→  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
 24→  return bytes.buffer;
 25→}
 26→
 27→// Restore session synchronously so downstream hooks see auth state on first render
 28→function getStoredSession() {
 29→  try {
 30→    const storedCredId = localStorage.getItem(LS_KEYS.credentialId);
 31→    const storedRawId = localStorage.getItem(LS_KEYS.rawId);
 32→    const storedAccount = localStorage.getItem(LS_KEYS.account);
 33→    if (storedCredId && storedRawId && storedAccount) {
 34→      const parsed = JSON.parse(storedAccount);
 35→      return {
 36→        credentialId: storedCredId,
 37→        rawId: base64urlDecode(storedRawId),
 38→        account: parsed.address,
 39→        username: parsed.username,
 40→      };
 41→    }
 42→  } catch {}
 43→  return null;
 44→}
