 46→export function usePasskeyAuth() {
 47→  const stored = getStoredSession();
 48→  const [isAuthenticated, setIsAuthenticated] = useState(!!stored);
 49→  const [account, setAccount] = useState(stored?.account || null);
 50→  const [username, setUsername] = useState(stored?.username || null);
 51→  const [credentialId, setCredentialId] = useState(stored?.credentialId || null);
 52→  const [rawId, setRawId] = useState(stored?.rawId || null);
 53→
 54→  const persistSession = useCallback((credId, rawIdBuf, address, user) => {
 55→    localStorage.setItem(LS_KEYS.credentialId, credId);
 56→    localStorage.setItem(LS_KEYS.rawId, base64urlEncode(rawIdBuf));
 57→    localStorage.setItem(LS_KEYS.account, JSON.stringify({ address, username: user }));
 58→    setCredentialId(credId);
 59→    setRawId(rawIdBuf);
 60→    setAccount(address);
 61→    setUsername(user);
 62→    setIsAuthenticated(true);
 63→  }, []);
 64→
 65→  const signup = useCallback(async (name) => {
 66→    if (!name || !name.trim()) throw new Error('Username required');
 67→    const trimmed = name.trim();
 68→
 69→    // 1. Create passkey credential
 70→    const challenge = crypto.getRandomValues(new Uint8Array(32));
 71→    const credential = await navigator.credentials.create({
 72→      publicKey: {
 73→        rp: { name: 'Login.com Smart Account', id: location.hostname },
 74→        user: {
 75→          id: crypto.getRandomValues(new Uint8Array(16)),
 76→          name: trimmed,
 77→          displayName: trimmed,
 78→        },
 79→        challenge,
 80→        pubKeyCredParams: [{ type: 'public-key', alg: -7 }], // ES256 = P-256
 81→        authenticatorSelection: {
 82→          authenticatorAttachment: 'platform',
 83→          residentKey: 'required',
 84→          userVerification: 'preferred',
 85→        },
 86→        timeout: 60000,
 87→      },
 88→    });
 89→
 90→    // 2. Extract public key (X, Y)
 91→    const publicKeyBytes = new Uint8Array(credential.response.getPublicKey());
 92→    let rawKey;
 93→    if (publicKeyBytes.length === 65 && publicKeyBytes[0] === 0x04) {
 94→      rawKey = publicKeyBytes;
 95→    } else {
 96→      const spkiOffset = publicKeyBytes.length - 65;
 97→      rawKey = publicKeyBytes.slice(spkiOffset);
 98→    }
 99→    if (rawKey[0] !== 0x04) throw new Error('Expected uncompressed public key (0x04 prefix)');
100→
101→    const pubKeyX = bufToHex(rawKey.slice(1, 33));
102→    const pubKeyY = bufToHex(rawKey.slice(33, 65));
103→    const credId = base64urlEncode(credential.rawId);
104→
105→    // 3. Register on server (deploys smart account)
106→    const resp = await fetch(`${PASSKEY_SERVER_URL}/api/register`, {
107→      method: 'POST',
108→      headers: { 'Content-Type': 'application/json' },
109→      body: JSON.stringify({ credentialId: credId, pubKeyX, pubKeyY, username: trimmed }),
110→    });
111→    const data = await resp.json();
112→    if (!resp.ok) throw new Error(data.error || 'Registration failed');
113→
114→    // 4. Persist session
115→    persistSession(credId, credential.rawId, data.address, trimmed);
116→    return { address: data.address, txHash: data.txHash };
117→  }, [persistSession]);
118→
119→  const login = useCallback(async () => {
120→    // 1. Discoverable credential assertion
121→    const challenge = crypto.getRandomValues(new Uint8Array(32));
122→    const assertion = await navigator.credentials.get({
123→      publicKey: {
124→        challenge,
125→        rpId: location.hostname,
126→        allowCredentials: [],
127→        userVerification: 'preferred',
128→        timeout: 60000,
129→      },
130→    });
131→
132→    const credId = base64urlEncode(assertion.rawId);
133→
134→    // 2. Look up account on server
135→    const resp = await fetch(`${PASSKEY_SERVER_URL}/api/login`, {
136→      method: 'POST',
137→      headers: { 'Content-Type': 'application/json' },
138→      body: JSON.stringify({ credentialId: credId }),
139→    });
140→    const data = await resp.json();
141→    if (!resp.ok) throw new Error(data.error || 'Login failed');
142→
143→    // 3. Persist session
144→    persistSession(credId, assertion.rawId, data.accountAddress, data.username);
145→    return { address: data.accountAddress, username: data.username };
146→  }, [persistSession]);
147→
148→  const logout = useCallback(() => {
149→    localStorage.removeItem(LS_KEYS.credentialId);
150→    localStorage.removeItem(LS_KEYS.rawId);
151→    localStorage.removeItem(LS_KEYS.account);
152→    setCredentialId(null);
153→    setRawId(null);
154→    setAccount(null);
155→    setUsername(null);
156→    setIsAuthenticated(false);
157→  }, []);
